import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"VisitorCounter Middleware","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/middleware/visitor.md","filePath":"03-developer/middleware/visitor.md"}`),a={name:`03-developer/middleware/visitor.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="visitorcounter-middleware" tabindex="-1">VisitorCounter Middleware <a class="header-anchor" href="#visitorcounter-middleware" aria-label="Permalink to “VisitorCounter Middleware”">​</a></h1><p>This Middleware records and updates information about website visitors. In addition to collecting visit data, it manages guest users&#39; access to the website when maintenance mode is active. The recorded information can be used to review visit statistics, identify the browsers and operating systems in use, analyze how users arrive at the website, and identify the most visited pages.</p><p>For each request, the Middleware first checks whether a visitor with the current IP address has a record from within the past hour. If no record meets these conditions, a new record is created in the visitors table. This record stores information such as the IP address, browser, operating system, browser version, referring domain, search engine keywords, whether a mobile device is being used, and the name of the requested page&#39;s Route. This information is extracted using the utilities available in the <code>TVisitor</code> class.</p><p>If a visitor with the same IP address is identified within the past hour, the existing record is updated. In this case, the <code>visit</code> counter is incremented by one, and the current page&#39;s Route name is also saved in the record. This way, visitor information is updated in the existing record instead of creating a new record for every request.</p><p>In this Middleware, visitor identification is based on a combination of the IP address and the record&#39;s last update time. Therefore, this mechanism does not definitively identify individuals or distinct sessions: multiple users sharing an IP address may be grouped into one record, or a user may be recorded in a new record after more than an hour has passed since the last update. Additionally, in this implementation, the <code>visit</code> counter is incremented for each eligible request that updates a record and does not necessarily correspond to the number of distinct visits or pages viewed by one person.</p><p>After recording or updating the information, the Middleware checks the website&#39;s maintenance mode status. If the <code>under</code> setting is <code>1</code> and the request belongs to an unauthenticated user, that user is redirected to the maintenance page. Otherwise, the request proceeds through the normal processing flow. Visitor information is therefore recorded before this restriction is applied, and guest users&#39; requests can also be included in visit statistics when maintenance mode is active.</p><p>Overall, <code>VisitorCounter</code> is responsible for recording and updating visitor information and providing basic data for analyzing website traffic. This Middleware also serves as one of the points where maintenance mode restrictions are applied to unauthenticated users. The collected information can be used in analytics and administrative sections, but the accuracy of the analysis depends on the limitations of IP-based identification and how visitor information is extracted.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};